// no goroutine-local storage: carry the request scope in the context instead
func (s *Server) handle(w http.ResponseWriter, r *http.Request) {
    ctx := context.WithValue(r.Context(), requestIDKey{}, newRequestID())
    s.serve(ctx, w, r)                     // ctx is the first parameter everywhere below
}

func requestID(ctx context.Context) string {  // typed accessor hides the key type
    id, _ := ctx.Value(requestIDKey{}).(string)
    return id
}
